import { INIT_NODE_IDS } from '../constants/Constants';

/** 系统初始化节点（角点、告警占位等），不可被用户选中 */
export function isInitNode(cell) {
  return cell?.id != null && INIT_NODE_IDS.includes(cell.id);
}

/** 图元未被 lock / group-lock */
export function isUnlockedCell(cell) {
  if (!cell?.id) {
    return false;
  }
  const lock = cell.prop?.('lock');
  const groupLock = cell.prop?.('group-lock');
  return !lock && !groupLock;
}

/**
 * Selection 插件 filter 规则：框选、点选、resetSelection 全选统一走此判断
 * @param {import('@antv/x6').Cell} cell
 * @param {{ drawing?: boolean }} [options]
 */
export function isSelectionFilterableCell(cell, { drawing = false } = {}) {
  if (!cell?.id || drawing) {
    return false;
  }
  if (isInitNode(cell)) {
    return false;
  }
  return isUnlockedCell(cell);
}

/**
 * 从 cell 列表中筛出可选图元（与 Selection filter 规则一致，不含 drawing 态）
 * @param {import('@antv/x6').Cell[]} cells
 */
export function filterSelectableCells(cells) {
  return (cells || []).filter((cell) => isSelectionFilterableCell(cell));
}

/**
 * 重置选区（先清空再选中），与框选共用 filter，默认 batch 合并 UI 更新
 * @param {import('@antv/x6').Graph} graph
 * @param {import('@antv/x6').Cell[]} cells
 * @param {{ batch?: boolean }} [options]
 */
export function resetGraphSelection(graph, cells, options = {}) {
  if (!graph?.resetSelection) {
    return;
  }
  const targets = filterSelectableCells(cells);
  const batch = options.batch !== false;
  if (!targets.length) {
    graph.cleanSelection?.();
    return;
  }
  graph.resetSelection(targets, { batch });
}

/**
 * 全选：预过滤 + Selection 插件 batch 模式，与框选 mouseup 行为对齐
 * @param {import('@antv/x6').Graph} graph
 */
export function selectAllCells(graph) {
  if (!graph?.getCells) {
    return;
  }
  resetGraphSelection(graph, graph.getCells());
}
