import {
  isPluginGeneratedKey,
  resolveStableDefinitionKey
} from '../../util/DefinitionKeyUtil.js';

function getCellList(json) {
  const cells = json?.cells;
  if (!cells) return [];
  if (Array.isArray(cells)) return cells;
  if (Array.isArray(cells.cells)) return cells.cells;
  return [];
}

function readCellKey(cell) {
  if (cell.key != null) return cell.key;
  if (cell.data && cell.data.key != null) return cell.data.key;
  return null;
}

function writeCellKey(cell, stableKey) {
  cell.key = stableKey;
  if (cell.data && typeof cell.data === 'object' && 'key' in cell.data) {
    delete cell.data.key;
  }
}

/**
 * v1.0 → v1.1：将插件生成的 nanoid definition key 迁移为稳定 key。
 */
export function migrateV1_0ToV1_1(json) {
  const cellList = getCellList(json);
  for (const cell of cellList) {
    const currentKey = readCellKey(cell);
    if (!isPluginGeneratedKey(currentKey)) continue;

    const stableKey = resolveStableDefinitionKey(cell);
    if (!stableKey || stableKey === currentKey) continue;

    writeCellKey(cell, stableKey);
  }
}
