/**
 * X6 refX/refY/refWidth/refHeight：面板 0–100，落库为 "n%"。
 * 兼容历史数据：0–1 小数仍可读；写入时统一为百分比字符串。
 */

export function parseRefPercent(cellValue) {
  if (cellValue === undefined || cellValue === null || cellValue === '') {
    return null;
  }
  const str = String(cellValue).trim();
  if (str.endsWith('%')) {
    const n = parseFloat(str);
    return Number.isNaN(n) ? null : Math.round(n);
  }
  const n = Number(cellValue);
  if (Number.isNaN(n)) {
    return null;
  }
  // 历史 0–1 比例
  if (n >= 0 && n <= 1) {
    return Math.round(n * 100);
  }
  // >1 或 <0 为像素等绝对值，面板不映射
  return null;
}

export function formatRefPercent(uiValue) {
  const n = Math.round(Number(uiValue));
  const clamped = Math.min(100, Math.max(0, Number.isNaN(n) ? 0 : n));
  return `${clamped}%`;
}

/** @param {{ defaultValue?: number }} options */
export function percentAttrFields(options = {}) {
  const defaultValue = options.defaultValue ?? 100;
  return {
    defaultValue,
    min: 0,
    max: 100,
    step: 1,
    format: formatRefPercent,
    parse: parseRefPercent
  };
}
