import { debounce } from 'lodash';
import { Dom, FunctionExt } from '@antv/x6';
import {
  SELECTION_BOX_DEBOUNCE_MS,
  SNAPLINE_CLEAN_MS
} from '../config/SystemConfig.js';
import { Selection } from '@antv/x6-plugin-selection';
import { Transform } from '@antv/x6-plugin-transform';
import { Snapline } from '@antv/x6-plugin-snapline';
import { Keyboard } from '@antv/x6-plugin-keyboard';
import { Clipboard } from '@antv/x6-plugin-clipboard';
import { History } from '@antv//x6-plugin-history';
import { Scroller } from '@antv/x6-plugin-scroller';
import { Export } from '@antv/x6-plugin-export';
import DrawEdge from '../event/DrawEdge';
import {
  isSelectionFilterableCell,
  isUnlockedCell
} from '../util/SelectionFilterUtil';
class ConfigGraph {
  isLock(cell) {
    return isUnlockedCell(cell);
  }
  init(graph, { beforeAddCommand = () => {} }) {
    graph.use(new Export());
    graph.use(
      new Scroller({
        enabled: true,
        pannable: false,
        pageVisible: true,
        pageBreak: true,
        // pageWidth: 100,
        // pageHeight: 100,
        autoResize: false
        // minVisibleWidth: 50,
        // minVisibleHeight: 50,
        // padding: 0
      })
    );
    /* graph.use(
      new Scroller({
        enabled: true,
        pannable: true,
        pageVisible: false,
        pageBreak: false,
        pageWidth: 1920,
        pageHeight: 1080,
        minVisibleWidth: 50,
        minVisibleHeight: 50,
        autoResize: false
      })
    ); */
    /* graph.use(
      new MiniMap({
        container: document.getElementById('minimap-container'),
        width: 300,
        height: 150,
        padding: 10
      })
    ); */
    let isDraw;
    DrawEdge.onStartDrawListening(() => {
      isDraw = true;
    });
    DrawEdge.onEndDrawListening(() => {
      isDraw = false;
    });
    //变形
    graph.use(
      new Transform({
        resizing: {
          enabled: (cell) => {
            if (isDraw) {
              return false;
            }
            return this.isLock(cell);
          },
          orthogonal: true,
          preserveAspectRatio: (node) => {
            return node.store.data.preserveAspectRatio;
          }
        },
        rotating: {
          enabled: (cell) => {
            if (isDraw) {
              return false;
            }
            // 临时禁用组节点旋转（组合功能旋转存在较多问题）
            if (cell?.isNode?.() && cell?.shape === 'custom-group-node') {
              return false;
            }
            return this.isLock(cell);
          }
        }
      })
    );
    //对齐线
    graph.use(
      new Snapline({
        enabled: true,
        clean: SNAPLINE_CLEAN_MS,
        resizing: true
      })
    );
    graph.use(
      new Keyboard({
        enabled: true,
        global: true
      })
    );
    //启用复制粘贴
    graph.use(
      new Clipboard({
        enabled: true,
        useLocalStorage: true
      })
    );
    //启用历史记录
    graph.use(
      new History({
        //不记录tools的添加/删除
        beforeAddCommand: (event, args) => {
          let isTrue = args.key != 'tools';
          if (isTrue) {
            isTrue = beforeAddCommand(event, args);
          }
          return isTrue;
        }
      })
    );

    //框选
    graph.use(
      new Selection({
        rubberband: true,
        strict: true,
        // movable: true,
        showNodeSelectionBox: false, //是否显示选中边框，此属性会降低大量图元拖拽时的性能
        showEdgeSelectionBox: true,
        rubberEdge: true,
        // modifiers: 'ctrl',
        pointerEvents: 'none', //解决框选与文本编辑冲突,但启用会导致following失效
        following: true, //拖拽时图元是否跟随，设置为false可提升大量图元时的拖拽性能
        filter: (cell) =>
          isSelectionFilterableCell(cell, { drawing: isDraw }),
      })
    );
    let transform = graph.getPlugin('transform');
    transform.createWidget = function (node) {
      this.clearWidgets();
      const widget = this.createTransform(node);
      if (widget) {
        widget.dispose = function () {
          this.remove();
          this.off();
          this.stopListening();
        };
      }
      if (widget) {
        this.widgets.set(node, widget);
        widget.on('*', (name, args) => {
          this.trigger(name, args);
          this.graph.trigger(name, args);
        });
      }
    };
    //获取官方插件对象
    let selection = graph.getPlugin('selection');
    //重写每次拖拽的更新方法，方法中去掉了原来判断showNodeSelectionBox是否启用的代码，并调用防抖函数
    selection.selectionImpl.confirmUpdate = function () {
      this.hide();
      debounceChangeBox(this);
      return 0;
    };
    //重写selection插件的大框初始化及位置更新方法
    selection.selectionImpl.updateContainer = function () {
      const origin = { x: Infinity, y: Infinity };
      const corner = { x: 0, y: 0 };
      const cells = this.collection.toArray();
      cells.forEach((cell) => {
        const view = this.graph.renderer.findViewByCell(cell);
        if (view) {
          const bbox = view.getBBox({
            useCellGeometry: true
          });
          origin.x = Math.min(origin.x, bbox.x);
          origin.y = Math.min(origin.y, bbox.y);
          corner.x = Math.max(corner.x, bbox.x + bbox.width);
          corner.y = Math.max(corner.y, bbox.y + bbox.height);
        }
      });
      Dom.css(this.selectionContainer, {
        position: 'absolute',
        pointerEvents: 'none',
        left: origin.x,
        top: origin.y,
        width: corner.x - origin.x,
        height: corner.y - origin.y
      });
      Dom.attr(
        this.selectionContainer,
        'data-selection-length',
        this.collection.length
      );
      if (this.collection.length > 1) {
        this.showSelected();
      }
      if (this.collection.length === 1) {
        // 此处开启后会导致拖拽大小结束后如果不松开鼠标画布锁死问题，此处忘记当时为什么要重新选中图元
        /*if (this.graph.renderer.findViewByCell(this.collection.cells[0])) {
          // this.graph.clearTransformWidgets();
          if (!this.collection.cells[0].isEdge()) {
            this.graph.createTransformWidget(this.collection.cells[0]);
          }
        }*/
      }
      const boxContent = this.options.content;
      if (boxContent) {
        if (typeof boxContent === 'function') {
          const content = FunctionExt.call(
            boxContent,
            this.graph,
            this,
            this.selectionContent
          );
          if (content) {
            this.selectionContent.innerHTML = content;
          }
        } else {
          this.selectionContent.innerHTML = boxContent;
        }
      }
      if (this.collection.length > 0 && !this.container.parentNode) {
        Dom.appendTo(this.container, this.graph.container);
      } else if (this.collection.length <= 0 && this.container.parentNode) {
        this.container.parentNode.removeChild(this.container);
      }
    };
    //大框位置更新防抖函数
    let debounceChangeBox = debounce(
      (thiz) => {
        thiz.updateContainer();
        thiz.showSelected();
      },
      SELECTION_BOX_DEBOUNCE_MS,
      {
        leading: false,
        trailing: true
      }
    );
  }
}
export default ConfigGraph;
