import { Node } from '@antv/x6';
import { cloneDeep } from 'lodash';
import CellPointController from '../store/CellPointController';
import { D3_G_NAME } from '../constants/Constants';
class SuperNode extends Node {
  constructor(metadata = {}) {
    super(metadata);
    // this.pointStor = {};
  }
  setPoint(point, attr) {
    console.log('superNode test', point, attr);
    let paObj = CellPointController.setPoint(point, attr);
    // this.pointStor[`${point.mpId}`]
    return paObj;
  }
  getPAName(mpKey, attrKey) {
    return CellPointController.getPAName(mpKey, attrKey);
  }
  propGroupLock(lock) {
    if (lock === undefined) {
      return this.prop('group-lock');
    }
    if (lock) {
      this.attr(D3_G_NAME + '/group', 'group-lock');
      this.prop('group-lock', true);
    } else {
      this.attr(D3_G_NAME + '/group', '');
      this.prop('group-lock', false);
    }
  }
  propFormat(format) {
    if (format) {
      this.prop('formulas/format', format, {
        silent: true
      });
    } else {
      return this.prop('formulas/format');
    }
  }
  propCases(cases) {
    if (cases) {
      this.prop('formulas/cases', cases, {
        silent: true
      });
    } else {
      return this.prop('formulas/cases');
    }
  }
  propAlarm(alarmsConfig) {
    if (alarmsConfig != null) {
      // 先移除再写入：X6 对 formulas/alarms 路径即使用 overwrite 也可能与旧 alarms[] 深度合并
      this.removeProp('formulas/alarms', { silent: true });
      const list = alarmsConfig.alarms;
      if (Array.isArray(list) && list.length > 0) {
        this.prop('formulas/alarms', cloneDeep(alarmsConfig), { silent: true });
      }
      return this;
    }
    return this.prop('formulas/alarms');
  }
  propTime(cases) {
    if (cases) {
      this.prop('formulas/time', cases, {
        silent: true
      });
    } else {
      return this.prop('formulas/time');
    }
  }
  getPoints() {
    let points = [];
    points.push(...this.getFormulasPoints());
    points.push(...this.getEventPoints());
    let result = [];
    points.forEach((point) => {
      let find = result.find((item) => {
        return point.mpId == item.mpId && point.attrId == item.attrId;
      });
      if (!find) {
        result.push(point);
      }
    });
    return result;
  }
  getFormulasPoints() {
    let points = [];

    points.push(...this.getCasesPoints());
    let point = this.getFormatPoints();
    point && points.push(point);

    let alarmPoints = this.getAlarmPoints();
    alarmPoints && points.push(...alarmPoints);
    return points;
  }
  getAlarmPoints() {
    let alarms = this.prop('formulas/alarms');
    let points = [];
    alarms?.alarms?.forEach((alarm) => {
      if (alarm.points) {
        points.push(...alarm.points);
      }
    });
    return points;
  }
  getCasesPoints() {
    let formulas = this.getProp('formulas');
    let points = [];
    formulas?.cases?.forEach((casePram) => {
      if (casePram.points) {
        points.push(...casePram.points);
      }
    });
    return points;
  }
  getFormatPoints() {
    let formulas = this.getProp('formulas');
    return formulas?.format?.point;
  }
  getEventPoints() {
    let events = this.getProp('events');
    let points = [];
    events?.forEach((event) => {
      event.actions?.forEach((action) => {
        if (
          action.point.attrId != null &&
          action.point.attrId != undefined &&
          action.point.attrId != ''
        ) {
          points.push(action.point);
        }
      });
    });
    return points;
  }
}
SuperNode.config({
  visible: true
});
export default SuperNode;
