import {
  NODE_TYPE_NAME,
  NODE_TYPES,
  SUPER_G_NAME
} from '../constants/Constants';

/** 图元定义分组键：groupKey + key，无 key 时回退 label */
export function getDefinitionGroupId(cell) {
  if (!cell) {
    return '';
  }
  const groupKey = cell.prop?.('groupKey') ?? '';
  const key = cell.prop?.('key');
  if (key != null && key !== '') {
    return `${groupKey}::${key}`;
  }
  const label = cell.prop?.('label') ?? '';
  return `${groupKey}::${label}`;
}

/**
 * 按图元定义分组
 * @param {import('@antv/x6').Cell[]} cells
 */
export function groupCellsByDefinition(cells) {
  const map = new Map();
  (cells || []).forEach((cell) => {
    if (!cell?.id) {
      return;
    }
    const id = getDefinitionGroupId(cell);
    if (!map.has(id)) {
      map.set(id, {
        id,
        groupKey: cell.prop?.('groupKey') ?? '',
        key: cell.prop?.('key') ?? '',
        label: cell.prop?.('label') ?? cell.prop?.('key') ?? '未命名',
        cells: []
      });
    }
    map.get(id).cells.push(cell);
  });
  return Array.from(map.values());
}

export function isGroupNode(cell) {
  return cell?.isNode?.() && cell?.shape === 'custom-group-node';
}

export function isEchartsNode(cell) {
  return cell?.getProp?.(NODE_TYPE_NAME) === NODE_TYPES.echarts;
}

/** 可用 markup 样式面板编辑的节点（不含边、图表、分组） */
export function isStyleEditableCell(cell) {
  if (!cell?.isNode?.()) {
    return false;
  }
  if (isGroupNode(cell) || isEchartsNode(cell)) {
    return false;
  }
  return true;
}

/** 可用属性面板批量编辑的节点 */
export function isBatchAttrEditableCell(cell) {
  return isStyleEditableCell(cell);
}

export function deepEqual(a, b) {
  if (a === b) {
    return true;
  }
  if (a == null || b == null) {
    return a === b;
  }
  if (typeof a !== typeof b) {
    return false;
  }
  if (typeof a !== 'object') {
    return false;
  }
  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) {
      return false;
    }
    return a.every((item, index) => deepEqual(item, b[index]));
  }
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) {
    return false;
  }
  return keysA.every((key) => deepEqual(a[key], b[key]));
}

/**
 * 聚合标量/对象配置项
 * @param {Array<unknown>} values
 */
export function aggregateScalar(values) {
  const hasUndefined = values.some((v) => v === undefined);
  const hasDefined = values.some((v) => v !== undefined);
  if (!hasDefined) {
    return { mixed: false, value: undefined, empty: true };
  }
  if (hasUndefined && hasDefined) {
    return { mixed: true, value: undefined, empty: false };
  }
  const defined = values.filter((v) => v !== undefined);
  const first = defined[0];
  const mixed = !defined.every((v) => deepEqual(v, first));
  return { mixed, value: mixed ? undefined : first, empty: false };
}

export function partitionDefinitionGroups(groups) {
  const styleGroups = (groups || []).filter(
    (group) =>
      group.cells?.length > 0 &&
      group.cells.every((cell) => isStyleEditableCell(cell))
  );
  const attrGroups = (groups || []).filter(
    (group) =>
      group.cells?.length > 0 &&
      group.cells.every((cell) => isBatchAttrEditableCell(cell))
  );
  return { styleGroups, attrGroups };
}

function readNodeOpacity(cell) {
  const fromSuper = cell.attr?.(`${SUPER_G_NAME}/opacity`);
  if (fromSuper != null) {
    return fromSuper;
  }
  return cell.store?.data?.opacity ?? 1;
}

function readNodeAngle(cell) {
  return cell.angle?.() ?? cell.store?.data?.angle ?? 0;
}

function readNodeSize(cell) {
  const size = cell.size?.();
  if (size) {
    return { width: size.width, height: size.height };
  }
  const stored = cell.store?.data?.size;
  return {
    width: stored?.width ?? 0,
    height: stored?.height ?? 0
  };
}

function readNodePosition(cell) {
  const pos = cell.position?.();
  if (pos) {
    return { x: pos.x, y: pos.y };
  }
  const stored = cell.store?.data?.position;
  return {
    x: stored?.x ?? 0,
    y: stored?.y ?? 0
  };
}

/**
 * 按当前位置相对偏移移动图元
 * @param {import('@antv/x6').Cell[]} cells
 * @param {{ x?: number, y?: number }} delta
 */
export function applyRelativePositionDelta(cells, delta = {}) {
  const dx = delta.x ?? 0;
  const dy = delta.y ?? 0;
  if (!dx && !dy) {
    return;
  }
  (cells || []).forEach((cell) => {
    if (!cell?.isNode?.()) {
      return;
    }
    const pos = readNodePosition(cell);
    cell.position(Math.round(pos.x + dx), Math.round(pos.y + dy), {
      deep: true
    });
  });
}

/**
 * 构建属性面板展示状态（支持 Mixed）
 * @param {import('@antv/x6').Cell[]} cells
 */
export function buildNodeAttrPanelState(cells) {
  const mixed = new Set();
  if (!cells?.length) {
    return { nodeAttr: null, mixed, isBatch: false };
  }
  if (cells.length === 1) {
    const cell = cells[0];
    const data = cell.store?.data ?? {};
    data.data = data.data ?? {};
    data.preserveAspectRatio = data.preserveAspectRatio ?? false;
    data.rotate3d = data.rotate3d ?? 'rotate3d(1, 1, 1, 0deg)';
    data.opacity = data.opacity ?? readNodeOpacity(cell);
    const nodeAttr = JSON.parse(JSON.stringify(data));
    nodeAttr?.status?.forEach((item) => {
      if (item.selected === undefined) {
        item.selected = '';
      }
    });
    return { nodeAttr, mixed, isBatch: false, mixedRanges: {}, cell };
  }

  const opacityAgg = aggregateScalar(cells.map((c) => readNodeOpacity(c)));
  const widthAgg = aggregateScalar(
    cells.map((c) => readNodeSize(c).width)
  );
  const heightAgg = aggregateScalar(
    cells.map((c) => readNodeSize(c).height)
  );
  const angleAgg = aggregateScalar(cells.map((c) => readNodeAngle(c)));
  const preserveAgg = aggregateScalar(
    cells.map((c) => c.store?.data?.preserveAspectRatio ?? false)
  );
  const posXAgg = aggregateScalar(
    cells.map((c) => readNodePosition(c).x)
  );
  const posYAgg = aggregateScalar(
    cells.map((c) => readNodePosition(c).y)
  );

  const nodeAttr = {
    opacity: opacityAgg.mixed ? undefined : opacityAgg.value,
    size: {
      width: widthAgg.mixed ? undefined : widthAgg.value,
      height: heightAgg.mixed ? undefined : heightAgg.value
    },
    angle: angleAgg.mixed ? undefined : angleAgg.value,
    preserveAspectRatio: preserveAgg.mixed
      ? undefined
      : preserveAgg.value
  };

  if (opacityAgg.mixed) mixed.add('opacity');
  if (widthAgg.mixed) mixed.add('size.width');
  if (heightAgg.mixed) mixed.add('size.height');
  if (angleAgg.mixed) mixed.add('angle');
  if (preserveAgg.mixed) mixed.add('preserveAspectRatio');
  if (posXAgg.mixed) mixed.add('position.x');
  if (posYAgg.mixed) mixed.add('position.y');

  const mixedRanges = {};
  if (widthAgg.mixed) {
    mixedRanges['size.width'] = formatNumericRange(
      cells.map((c) => readNodeSize(c).width)
    );
  }
  if (heightAgg.mixed) {
    mixedRanges['size.height'] = formatNumericRange(
      cells.map((c) => readNodeSize(c).height)
    );
  }
  if (opacityAgg.mixed) {
    mixedRanges.opacity = formatNumericRange(
      cells.map((c) => readNodeOpacity(c))
    );
  }
  if (angleAgg.mixed) {
    mixedRanges.angle = formatNumericRange(cells.map((c) => readNodeAngle(c)));
  }
  if (posXAgg.mixed) {
    mixedRanges['position.x'] = formatNumericRange(
      cells.map((c) => readNodePosition(c).x)
    );
  }
  if (posYAgg.mixed) {
    mixedRanges['position.y'] = formatNumericRange(
      cells.map((c) => readNodePosition(c).y)
    );
  }

  return { nodeAttr, mixed, isBatch: true, mixedRanges, cell: null };
}

/** 数值差异化范围展示，如 100~150 */
export function formatNumericRange(values) {
  const nums = [];
  (values || []).forEach((v) => {
    if (v === undefined || v === null || v === '') {
      return;
    }
    const n = typeof v === 'number' ? v : Number(v);
    if (!Number.isNaN(n)) {
      nums.push(n);
    }
  });
  if (!nums.length) {
    return '';
  }
  const min = Math.min(...nums);
  const max = Math.max(...nums);
  if (min === max) {
    return String(min);
  }
  return `${min}~${max}`;
}

/** 文本/枚举类差异化范围，多个不同值用 / 分隔 */
export function formatDistinctValueRange(values) {
  const unique = [
    ...new Set(
      (values || [])
        .filter((v) => v !== undefined && v !== null && String(v).trim() !== '')
        .map((v) => String(v))
    )
  ];
  if (!unique.length) {
    return '';
  }
  if (unique.length === 1) {
    return unique[0];
  }
  return unique.join(' / ');
}

/**
 * 构建批量文本/状态面板数据
 * @param {import('@antv/x6').Cell[]} cells
 * @param {Function} recursionMarkup
 */
export function buildBatchTextStatusPanelState(cells, recursionMarkup) {
  if (!cells?.length || cells.length <= 1) {
    return { textNodes: [], textFields: {}, statusList: [] };
  }
  const primary = cells[0];
  const attrs = JSON.parse(JSON.stringify(primary.getAttrs?.() ?? {}));
  const markup = recursionMarkup(primary.getMarkup?.() ?? [], attrs);
  const textNodes = (markup || []).filter((item) => item.tagName === 'text');
  const textFields = {};

  textNodes.forEach((item) => {
    const values = cells.map(
      (c) => c.attr?.(`${item.selector}/text`) ?? ''
    );
    const agg = aggregateScalar(values);
    textFields[item.selector] = {
      value: agg.mixed ? '' : agg.value ?? '',
      mixed: agg.mixed,
      range: agg.mixed ? formatDistinctValueRange(values) : ''
    };
  });

  const statusTemplate = JSON.parse(
    JSON.stringify(primary.store?.data?.status ?? [])
  );
  const statusList = statusTemplate.map((statuDef) => {
    const selectedValues = cells.map((c) => {
      const arr = c.store?.data?.status ?? [];
      const found = arr.find((s) => s.label === statuDef.label);
      return found?.selected ?? '';
    });
    const agg = aggregateScalar(selectedValues);
    return {
      label: statuDef.label,
      status: statuDef.status,
      selected: agg.mixed ? '' : agg.value ?? '',
      mixed: agg.mixed,
      range: agg.mixed ? formatDistinctValueRange(selectedValues) : ''
    };
  });

  return { textNodes, textFields, statusList };
}

/** X6/SVG 图片地址可能落在不同 attr 键上，展示与聚合时统一为 xlinkHref */
export const IMAGE_SRC_ATTR_KEYS = ['xlinkHref', 'href', 'xlink:href'];

export function readImageSrcFromFlat(flat) {
  if (!flat || typeof flat !== 'object') {
    return undefined;
  }
  for (const key of IMAGE_SRC_ATTR_KEYS) {
    const value = flat[key];
    if (value !== undefined && value !== null && value !== '') {
      return value;
    }
  }
  return undefined;
}

/** 将扁平 attrs 中的图片地址归一到 xlinkHref，避免 href/xlinkHref 重复项干扰聚合 */
export function normalizeFlatImageAttrs(flat) {
  if (!flat || typeof flat !== 'object') {
    return {};
  }
  const result = { ...flat };
  const imageSrc = readImageSrcFromFlat(result);
  IMAGE_SRC_ATTR_KEYS.forEach((key) => {
    delete result[key];
  });
  if (imageSrc !== undefined) {
    result.xlinkHref = imageSrc;
  }
  return result;
}

/**
 * 聚合多份扁平 attrs（含 Mixed 键）
 * @param {Record<string, unknown>[]} flats
 */
export function aggregateFlatAttrs(flats) {
  const normalized = (flats || []).map((flat) => normalizeFlatImageAttrs(flat));
  const allKeys = new Set();
  normalized.forEach((flat) => {
    Object.keys(flat).forEach((key) => allKeys.add(key));
  });

  const attrData = {};
  const mixedKeys = new Set();

  allKeys.forEach((key) => {
    const values = normalized.map((flat) => flat[key]);
    const agg = aggregateScalar(values);
    if (agg.mixed) {
      mixedKeys.add(key);
    } else if (!agg.empty) {
      attrData[key] = agg.value;
    }
  });

  return { attrData, mixedKeys };
}

/**
 * 扁平化 selector 下 attrs 并聚合（供样式 Mixed）
 * @param {import('@antv/x6').Cell[]} cells
 * @param {string} selector
 * @param {Function} keysToString
 */
export function aggregateSelectorFlatAttrs(cells, selector, keysToString) {
  const flats = (cells || []).map((cell) =>
    keysToString(
      '',
      JSON.parse(JSON.stringify(cell.getAttrByPath(selector) ?? {}))
    )
  );
  return aggregateFlatAttrs(flats);
}
