import {
  applySingleSelectChrome,
  clearCellEditChrome,
  clearMultiSelectionChrome
} from './CellSelectionUtil';
import { filterSelectableCells } from './SelectionFilterUtil';
import { LARGE_SELECTION_THRESHOLD } from '../config/SystemConfig.js';

export { LARGE_SELECTION_THRESHOLD } from '../config/SystemConfig.js';

export function isLargeSelection(cellCount) {
  return cellCount > LARGE_SELECTION_THRESHOLD;
}

export { filterSelectableCells } from './SelectionFilterUtil';

/**
 * 根据当前选区同步画布编辑控件（变形框 / 节点四向按钮 / 边编辑工具）
 * @param {import('@antv/x6').Graph} graph
 * @param {import('@antv/x6').Cell[]} cells 已过滤的可选图元
 */
export function syncSelectionChrome(graph, cells) {
  if (!graph) {
    return;
  }
  if (cells.length > 1) {
    clearMultiSelectionChrome(graph);
    return;
  }
  if (cells.length === 1) {
    applySingleSelectChrome(graph, cells[0]);
    return;
  }
  graph.clearTransformWidgets?.();
}

/**
 * 选区变化调度器：同一帧内多次 selection:changed 合并为一次同步
 * @param {import('@antv/x6').Graph} graph
 */
export function createSelectionSyncController(graph) {
  let rafId = null;
  const hooks = [];

  const flush = () => {
    rafId = null;
    if (!graph) {
      return;
    }
    const cells = filterSelectableCells(graph.getSelectedCells());
    syncSelectionChrome(graph, cells);
    hooks.forEach((hook) => {
      try {
        hook(cells, graph);
      } catch (err) {
        console.error('[SelectionSync] hook failed:', err);
      }
    });
  };

  const schedule = () => {
    if (rafId != null) {
      return;
    }
    rafId = requestAnimationFrame(flush);
  };

  const onSelectionChanged = ({ removed } = {}) => {
    if (removed?.length) {
      removed.forEach(clearCellEditChrome);
    }
    schedule();
  };

  return {
    bind() {
      graph.on('selection:changed', onSelectionChanged);
    },
    dispose() {
      graph.off('selection:changed', onSelectionChanged);
      if (rafId != null) {
        cancelAnimationFrame(rafId);
        rafId = null;
      }
    },
    flushNow() {
      if (rafId != null) {
        cancelAnimationFrame(rafId);
        rafId = null;
      }
      flush();
    },
    onSync(hook) {
      if (!hook || hooks.includes(hook)) {
        return;
      }
      hooks.push(hook);
    },
    offSync(hook) {
      const index = hooks.indexOf(hook);
      if (index >= 0) {
        hooks.splice(index, 1);
      }
    },
    clearHooks() {
      hooks.length = 0;
    }
  };
}
