import {
  compareGraphVersion,
  DEFAULT_GRAPH_FORMAT_VERSION,
  GRAPH_FORMAT_VERSION,
  stampGraphConfigVersion
} from './GraphFormatVersion.js';
import { migrations } from './migrations/index.js';

/**
 * 按版本链升级图纸 JSON，返回是否执行了升级步骤。
 */
export function upgradeGraphJson(json) {
  if (!json || typeof json !== 'object') {
    return { json, upgraded: false };
  }

  if (!json.graph || typeof json.graph !== 'object') {
    json.graph = {};
  }

  let version = json.graph.version ?? DEFAULT_GRAPH_FORMAT_VERSION;
  let upgraded = false;

  for (const migration of migrations) {
    if (compareGraphVersion(version, migration.version) < 0) {
      migration.up(json);
      version = migration.version;
      upgraded = true;
    }
  }

  if (compareGraphVersion(json.graph.version ?? version, GRAPH_FORMAT_VERSION) < 0) {
    json.graph.version = GRAPH_FORMAT_VERSION;
    upgraded = true;
  }

  return { json, upgraded };
}

/**
 * 编辑器加载图纸前的统一预处理：高版本拦截 + 自动升级。
 */
export function prepareGraphJsonForLoad(json) {
  if (!json || typeof json !== 'object') {
    return {
      json,
      upgraded: false,
      blocked: true,
      message: '图纸数据无效，无法加载'
    };
  }

  if (!json.graph || typeof json.graph !== 'object') {
    json.graph = {};
  }

  const currentVersion = json.graph.version ?? DEFAULT_GRAPH_FORMAT_VERSION;

  if (compareGraphVersion(currentVersion, GRAPH_FORMAT_VERSION) > 0) {
    return {
      json,
      upgraded: false,
      blocked: true,
      message: `图纸格式版本 ${currentVersion} 高于当前编辑器支持版本 ${GRAPH_FORMAT_VERSION}，请升级组态包后重试`
    };
  }

  const { json: upgradedJson, upgraded } = upgradeGraphJson(json);

  return {
    json: upgradedJson,
    upgraded,
    blocked: false,
    message: null
  };
}

export {
  GRAPH_FORMAT_VERSION,
  DEFAULT_GRAPH_FORMAT_VERSION,
  compareGraphVersion,
  stampGraphConfigVersion
};
